class Solution {
    public boolean isAlienSorted(String[] words,String order){
        int[] rank=new int[26];
        for(int i=0;i<26;i++)rank[order.charAt(i)-'a']=i;
        for(int w=1;w<words.length;w++){
            String a=words[w-1],b=words[w];
            int i=0;
            while(i<a.length()&&i<b.length()&&a.charAt(i)==b.charAt(i))i++;
            if(i==b.length()&&i<a.length())return false;
            if(i<a.length()&&i<b.length()&&rank[a.charAt(i)-'a']>rank[b.charAt(i)-'a'])return false;
        }
        return true;
    }
}

